     1	/**
     2	 * Event Service Client for Expo/React Native
     3	 * Fetches events from Supabase REST API directly
     4	 * 
     5	 * ARCHITECTURE:
     6	 * - PRIMARY: Supabase REST API (direct, no backend server needed)
     7	 * - MOBILE: Works from any network (cellular, LAN, WiFi)
     8	 * 
     9	 * IMPORTANT: Direct Supabase access enables true mobile/offline support.
    10	 */
    11	
    12	// Supabase Project Configuration
    13	// Note: For production, configure RLS policies to allow public read access
    14	// and use the anon key instead of service role key
    15	const SUPABASE_URL = 'https://bsllkpvkowwndhhxtlln.supabase.co';
    16	const SUPABASE_ANON_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImJzbGxrcHZrb3d3bmRoaHh0bGxuIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3MzMwMDQzNCwiZXhwIjoyMDg4ODc2NDM0fQ.2BJFgNoS0iP53WuPS_lyjNlHjy11_VLjKmcrhf5Dyis';
    17	
    18	/**
    19	 * Fetch events from Supabase REST API
    20	 * This is the PRIMARY source for events in production
    21	 * Works from mobile (cellular/WiFi) without needing local backend server
    22	 */
    23	export async function fetchFromSupabase() {
    24	  try {
    25	    // Supabase REST API endpoint for events table
    26	    // Request specific columns to avoid column not found errors
    27	    const url = `${SUPABASE_URL}/rest/v1/events?select=id,source,source_id,title_sv,title_en,start_time,end_time,venue_id,lat,lng,is_free,price_min_sek,price_max_sek,ticket_url,image_url,status,category_slug&status=eq.published&order=start_time.asc&limit=100`;
    28	    
    29	    const response = await fetch(url, {
    30	      method: 'GET',
    31	      headers: {
    32	        'apikey': SUPABASE_ANON_KEY,
    33	        'Authorization': `Bearer ${SUPABASE_ANON_KEY}`,
    34	        'Content-Type': 'application/json',
    35	        'Accept': 'application/json'
    36	      },
    37	    });
    38	
    39	    if (!response.ok) {
    40	      const errorText = `HTTP ${response.status}: ${response.statusText}`;
    41	      console.error('[EventService] Supabase fetch failed:', errorText);
    42	      return {
    43	        events: [],
    44	        sources: [],
    45	        metadata: {
    46	          data_source: 'supabase',
    47	          fallback_used: false,
    48	          error: errorText
    49	        }
    50	      };
    51	    }
    52	
    53	    const events = await response.json();
    54	    
    55	    // Normalize events to match expected format
    56	    const normalizedEvents = events.map(event => ({
    57	      id: event.id,
    58	      source: event.source,
    59	      source_id: event.source_id,
    60	      title: event.title_sv || event.title_en || 'Untitled',
    61	      title_sv: event.title_sv,
    62	      title_en: event.title_en,
    63	      date: event.start_time ? event.start_time.split('T')[0] : null,
    64	      start_time: event.start_time,
    65	      end_time: event.end_time,
    66	      venue_id: event.venue_id,
    67	      lat: event.lat,
    68	      lng: event.lng,
    69	      is_free: event.is_free,
    70	      price_min: event.price_min_sek,
    71	      price_max: event.price_max_sek,
    72	      ticket_url: event.ticket_url,
    73	      image_url: event.image_url,
    74	      url: event.ticket_url,
    75	      status: event.status,
    76	      category: event.category_slug
    77	    }));
    78	    
    79	    // Extract unique sources
    80	    const sourceCounts = {};
    81	    normalizedEvents.forEach(event => {
    82	      sourceCounts[event.source] = (sourceCounts[event.source] || 0) + 1;
    83	    });
    84	
    85	    return {
    86	      events: normalizedEvents,
    87	      sources: Object.keys(sourceCounts),
    88	      source_counts: sourceCounts,
    89	      count: normalizedEvents.length,
    90	      metadata: {
    91	        data_source: 'supabase',
    92	        fallback_used: false,
    93	        available_sources: Object.keys(sourceCounts),
    94	        total_count: normalizedEvents.length
    95	      }
    96	    };
    97	  } catch (error) {
    98	    console.error('[EventService] Supabase fetch failed:', error.message);
    99	    return {
   100	      events: [],
   101	      sources: [],
   102	      metadata: {
   103	        data_source: 'supabase',
   104	        fallback_used: false,
   105	        error: error.message
   106	      }
   107	    };
   108	  }
   109	}
   110	
   111	/**
   112	 * Aliases for backward compatibility with existing app code
   113	 */
   114	export async function fetchEventsSupabaseOnly() {
   115	  return fetchFromSupabase();
   116	}
   117	
   118	export async function fetchEventsWithFallback() {
   119	  return fetchFromSupabase();
   120	}
   121	
   122	export async function fetchAllEventsViaServer() {
   123	  return fetchFromSupabase();
   124	}
   125	
   126	// Export for use in App.js
   127	export const fetchEvents = fetchFromSupabase;
   128	export const fetchEventsFromSupabase = fetchFromSupabase;
   129	
   130	// Export constants for debugging
   131	export { SUPABASE_URL };
